contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount, uint cashOutAmount) public payable {
        require(address(this).balance >= depositAmount, "need base ETH");

        // Make a valid deposit first, so the caller's balance exists.
        uint preDepositBalance = c.balances(address(this));
        c.Deposit{value: depositAmount}();
        uint postDepositBalance = c.balances(address(this));
        require(postDepositBalance >= preDepositBalance, "deposit did not increase balance");

        uint beforeCallerBalance = c.balances(address(this));
        uint beforeContractBalance = address(c).balance;

        // Decide the expected reachability of the cashout condition.
        bool shouldComplete = cashOutAmount <= beforeCallerBalance;

        bool reverted;
        try c.CashOut(cashOutAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterCallerBalance = c.balances(address(this));
        uint afterContractBalance = address(c).balance;

        // General rule: no revert iff requested amount is within balance;
        // on success the balance drops by exactly cashOutAmount and c loses
        // exactly cashOutAmount Ether to this test contract.
        assert(
            (reverted == !shouldComplete) &&
            (
                !shouldComplete ||
                (
                    afterCallerBalance == beforeCallerBalance - cashOutAmount &&
                    address(this).balance >= cashOutAmount &&
                    beforeContractBalance >= cashOutAmount &&
                    afterContractBalance == beforeContractBalance - cashOutAmount
                )
            )
        );
    }

    receive() external payable {}
}

