        c = _c;
    }

    function run(uint depositAmount, uint cashOutAmount) public payable {
        // Need enough ETH to fund the deposit.
        require(address(this).balance >= depositAmount, "need base ETH");
        require(cashOutAmount > 0, "must cash out a positive amount");

        // Make a valid deposit first so the caller's balance is positive.
        c.Deposit{value: depositAmount}();

        uint beforeCallerBalance = c.balances(address(this));
        uint beforeContractBalance = address(c).balance;

        // Focus the rule on cashing out exactly the deposited balance.
        require(cashOutAmount == beforeCallerBalance, "cash out exactly the full balance");
        require(beforeContractBalance >= cashOutAmount, "c must hold enough ETH");

        bool reverted;
        try c.CashOut(cashOutAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterCallerBalance = c.balances(address(this));
        uint afterContractBalance = address(c).balance;

        // The call must succeed and zero the caller's balance, moving exactly
        // cashOutAmount Ether out of c and into this test contract.
        assert(
            !reverted &&
            afterCallerBalance == 0 &&
            beforeContractBalance >= cashOutAmount &&
            afterContractBalance == beforeContractBalance - cashOutAmount &&
            address(this).balance >= cashOutAmount
        );
    }

    receive() external payable {}
}

