contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint depositAmt, uint cashOutAmt) public payable {
        require(address(this).balance >= depositAmt + cashOutAmt);

        uint beforeBal = c.balances(address(this));
        uint beforeContractEther = address(c).balance;
        uint beforeTestEther = address(this).balance;

        uint offer = depositAmt + c.MinDeposit();
        c.Deposit{value: offer}();

        uint afterDepositBal = c.balances(address(this));
        uint afterDepositContractEther = address(c).balance;

        bool reverted;
        try c.CashOut{value: cashOutAmt}(cashOutAmt) { reverted = false; } catch { reverted = true; }

        uint afterBal = c.balances(address(this));
        uint afterContractEther = address(c).balance;
        uint afterTestEther = address(this).balance;

        if (cashOutAmt <= afterDepositBal) {
            assert(!reverted);
            assert(afterBal == afterDepositBal - cashOutAmt);
            assert(afterContractEther == afterDepositContractEther - cashOutAmt);
            assert(afterTestEther == beforeTestEther - offer + cashOutAmt);
        } else {
            assert(reverted);
            assert(afterBal == afterDepositBal);
            assert(afterContractEther == afterDepositContractEther);
            assert(afterTestEther == beforeTestEther - offer);
        }

        assert(beforeBal == 0);
        assert(afterDepositContractEther == beforeContractEther + offer);
        assert(afterContractEther >= 0);
        assert(afterTestEther >= 0);
        assert(afterBal <= afterDepositBal);
    }

    receive() external payable {}
}

